mapper.select:
SELECT COUNT(*)
FROM learning_lesson
WHERE user_id = #{userId}
  AND course_id = #{courseId}
  AND status = 2

mapper.update:
UPDATE course c
SET c.rating = COALESCE((
        SELECT AVG(cr.rating)
        FROM course_review cr
        WHERE cr.course_id = #{courseId}
    ), 0),
    c.review_count = (
        SELECT COUNT(*)
        FROM course_review cr
        WHERE cr.course_id = #{courseId}
    )
WHERE c.id = #{courseId}
